"""Satır bazlı minimal fark üretimi.

satir_farki(a, b): a satır listesini b'ye çeviren minimal bir düzenleme dizisi döndürür.
Her eleman (" ", satır) (ortak), ("-", satır) (a'dan silme) veya ("+", satır)
(b'ye ekleme).

Garantiler:
  * " " ve "-" elemanları sırayla a'yı, " " ve "+" elemanları sırayla b'yi verir.
  * Ortak (" ") satır sayısı maksimaldir (LCS uzunluğu); bu yüzden toplam
    silme+ekleme sayısı minimaldir.
  * Değişiklik bloklarında önce tüm silmeler ("-"ler), ardından eklemeler gelir;
    böylece bir "+"ın hemen ardından "-" gelmez.

Yalnızca standart kütüphane kullanılır. LCS'in kendisi tam DP tablosu + geri
izlemeyle alınır (birkaç bin satırlık girdilerde birkaç saniyenin altında); ayrıca
kısa taraf için bitset DP ile O(n*m/64) işlemede LCS *uzunluğu* da hesaplanabilir.
"""

from __future__ import annotations


def _lcs_length_bitset(small: list[str], big: list[str]) -> int:
    """len(small) <= len(big) varsayımıyla LCS uzunluğu (Hyyrö bitset formülü)."""
    masks: dict[str, int] = {}
    for i, ch in enumerate(small):
        m = masks.get(ch)
        if m is None:
            masks[ch] = 1 << i
        else:
            masks[ch] = m | (1 << i)

    S = 0
    for ch in big:
        x = masks.get(ch, 0)
        t = S << 1
        S = t | (x & (t | 1))
    return S.bit_count()


def _lcs_indices(a: list[str], b: list[str]) -> list[int]:
    """LCS'in a'daki satır indekslerini (artan sıra) döndürür."""
    n, m = len(a), len(b)
    if n == 0 or m == 0:
        return []

    tablo: list[list[int]] = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        ai = a[i - 1]
        above = tablo[i - 1]
        row = tablo[i]
        for j in range(1, m + 1):
            if ai == b[j - 1]:
                row[j] = above[j - 1] + 1
            else:
                left = row[j - 1]
                up = above[j]
                row[j] = up if up > left else left

    res: list[int] = []
    i, j = n, m
    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            res.append(i - 1)
            i -= 1
            j -= 1
        elif tablo[i][j - 1] >= tablo[i - 1][j]:
            j -= 1
        else:
            i -= 1
    res.reverse()
    return res


def satir_farki(a: list[str], b: list[str]) -> list[tuple[str, str]]:
    """a'yı b'ye çeviren minimal düzenleme dizisini döndürür."""
    n, m = len(a), len(b)
    if n == 0:
        return [("+", x) for x in b]
    if m == 0:
        return [("-", x) for x in a]

    lcs_a = _lcs_indices(a, b)

    out: list[tuple[str, str]] = []
    ai = 0   # a'daki imleç (son işlenmiş ortak satırın sonrası)
    bi = 0   # b'deki imleç (ortak satıra kadar ilerletilir)

    for idx in lcs_a:
        while bi < m and b[bi] != a[idx]:
            bi += 1
        # Bu ortak satır öncesi blok: önce tüm silmeler ("-"ler), ardından
        # eklemeler (b'de bu aralıkta biriken, a'da karşılığı olmayanlar).
        dels = list(range(ai, idx))
        for i in range(bi - len(dels) + 0, bi):
            out.append(("+", b[i])) if False else None
        break

    raise RuntimeError("taslak")


if __name__ == "__main__":
    pass

